# Builds the CxxWrap wrapper DLL (deps/usr/bin/libquantumx_wrap.dll).
#
# Requirements
#   * 32-bit Julia (the HBM DLL is 32 bit):          juliaup add release~x86
#   * 32-bit MinGW-w64 g++ (MSYS2 "mingw32" env):    pacman -S mingw-w64-i686-gcc
#
# Environment variables (optional)
#   QUANTUMX_SDK_DIR  folder with HBM_QX_Framework.{h,lib,dll}
#                     (default: "../../QuantumX Low-level API" next to this package)
#   QUANTUMX_CXX      path of the i686 g++ (default: C:\msys64\mingw32\bin\g++.exe)
#
# The C++ runtime (libstdc++/libgcc/winpthread) is linked statically: Julia's 32-bit
# runtime uses SJLJ exceptions while MSYS2's mingw32 GCC uses DWARF-2, so the wrapper
# must not load MSYS2's libstdc++-6.dll next to Julia's.

using CxxWrap
using Libdl

Sys.WORD_SIZE == 32 || error("QuantumX must be built with a 32-bit Julia (HBM_QX_Framework.dll is 32 bit). " *
                             "Install one with `juliaup add release~x86` and run `julia +release~x86`.")
Sys.iswindows() || error("QuantumX supports Windows only.")

const PKGDIR = normpath(joinpath(@__DIR__, ".."))
const SDK = normpath(get(ENV, "QUANTUMX_SDK_DIR", joinpath(PKGDIR, "..", "QuantumX Low-level API")))
const CXX = get(ENV, "QUANTUMX_CXX", raw"C:\msys64\mingw32\bin\g++.exe")

for f in ("HBM_QX_Framework.h", "HBM_QX_Framework.lib", "HBM_QX_Framework.dll", "pthreadVC2.dll")
    isfile(joinpath(SDK, f)) || error("$f not found in SDK folder $SDK (set ENV[\"QUANTUMX_SDK_DIR\"])")
end
isfile(CXX) || error("32-bit g++ not found at $CXX. Install MSYS2 and `pacman -S mingw-w64-i686-gcc`, " *
                     "or set ENV[\"QUANTUMX_CXX\"].")

const CXXBIN = dirname(CXX)
withpath(cmd) = addenv(cmd, "PATH" => CXXBIN * ";" * get(ENV, "PATH", ""))

target = strip(read(withpath(`$CXX -dumpmachine`), String))
startswith(target, "i686") || error("$CXX targets $target; an i686 (32-bit) compiler is required.")

const CXXWRAP_PREFIX = CxxWrap.prefix_path()
const JULIA_INC = normpath(joinpath(Sys.BINDIR, "..", "include", "julia"))
const JULIA_LIB = normpath(joinpath(Sys.BINDIR, "..", "lib", "libjulia.dll.a"))

const SRC = joinpath(@__DIR__, "src", "quantumx_wrap.cpp")
const OUTDIR = joinpath(@__DIR__, "usr", "bin")
const OUT = joinpath(OUTDIR, "libquantumx_wrap.dll")
mkpath(OUTDIR)

cmd = `$CXX -std=c++17 -O2 -shared -o $OUT $SRC
       -I$(joinpath(CXXWRAP_PREFIX, "include")) -I$JULIA_INC -I$SDK
       -D_WIN32 -D_LITTLE_ENDIAN -DNOMINMAX -Wno-pragmas -Wno-attributes
       $(joinpath(CXXWRAP_PREFIX, "lib", "libcxxwrap_julia.dll.a")) $JULIA_LIB
       $(joinpath(SDK, "HBM_QX_Framework.lib"))
       -static-libstdc++ -static-libgcc -Wl,-Bstatic -lwinpthread -Wl,-Bdynamic`

@info "Compiling QuantumX wrapper" compiler = CXX target sdk = SDK cxxwrap = pkgversion(CxxWrap)
run(withpath(cmd))

open(joinpath(@__DIR__, "deps.jl"), "w") do io
    println(io, "# generated by deps/build.jl – do not edit")
    println(io, "const libquantumx_wrap = ", repr(OUT))
    println(io, "const QX_SDK_DIR = ", repr(SDK))
    println(io, "const QX_BUILT_WITH_CXXWRAP = v\"", pkgversion(CxxWrap), "\"")
end
@info "QuantumX wrapper built" OUT
